import {KITS} from './skills.js?v=25';
import {basicInterval,resolveStrike} from './combat.js?v=25';
import {SKILL_UNLOCK,skillGrowth} from './skill-growth.js?v=25';
import {rngFrom} from './bot-society.js?v=25';
export function createMatch(a,b,{seed=1,watch=false,equalized=true}={}){const base=a.stats;return{time:0,watch,equalized,rng:rngFrom(seed),events:[],pending:[],winner:null,done:false,autoBasic:false,fighters:[a,b].map((f,i)=>{let st={...f.stats};if(equalized){const atk=base.atk||Math.max(base.af,base.am);st={...base,atk,af:atk,am:atk,range:f.stats.range,speed:f.stats.speed};}return{...f,st,hp:st.hp,mp:st.mp,x:i?13:3,y:i?6:5,cd:Array(7).fill(0),basic:0,lock:0,stun:0,shield:0,buffs:{},damage:0,attacks:0,potion:false,attackAnim:0};})};}
export function arenaAction(m,n,index){if(m.done)return false;const f=m.fighters[n],t=m.fighters[1-n];if(f.lock>0||f.stun>0)return false;const distance=Math.abs(f.x-t.x);if(index===null){if(f.basic>0||distance>f.st.range)return false;f.basic=basicInterval(f.st,{haste:f.buffs.haste>0||f.buffs.horizon>0});f.lock=.18;}else{const sk=KITS[f.classId][index];if(!sk||f.cd[index]>0||f.level<(SKILL_UNLOCK[index]||1)||sk.cost>f.mp)return false;if(sk.coef>0&&distance>sk.range)return false;f.mp-=sk.cost;f.cd[index]=sk.cd*(1-f.st.cdr);f.lock=Math.max(.2,sk.cast||.3);if(['blink','backstep','break'].includes(sk.kind)){f.x=Math.max(0,Math.min(16,f.x+Math.sign(f.x-t.x||-1)*3));f.stun=0;}if(['dash','intercept'].includes(sk.kind))f.x=t.x+Math.sign(f.x-t.x||-1)*1.5;if(!sk.coef){f.buffs[sk.kind]=sk.duration||5;if(sk.shield)f.shield=f.st.hp*sk.shield;m.events.push({time:m.time,n,label:sk.name,damage:0});return true;}}
 const sk=index===null?null:KITS[f.classId][index];f.attackAnim=.5;f.attacks++;m.pending.push({n,index,wait:(sk?.cast||.05)+Math.min(.5,distance/25),coefficient:sk?.coef||1,stun:sk?.stun||0});return true;}
export function arenaMove(m,n,direction,dt){const f=m.fighters[n];if(!m.done&&f.stun<=0&&f.lock<=0)f.x=Math.max(0,Math.min(16,f.x+direction*f.st.speed*dt));}
export function tickMatch(m,dt){if(m.done)return;dt=Math.max(0,Math.min(.08,dt));m.time+=dt;for(let n=0;n<2;n++){const f=m.fighters[n],t=m.fighters[1-n];for(const k of ['basic','lock','stun','attackAnim'])f[k]=Math.max(0,f[k]-dt);f.cd=f.cd.map(c=>Math.max(0,c-dt));for(const k of Object.keys(f.buffs))f.buffs[k]-=dt;f.mp=Math.min(f.st.mp,f.mp+f.st.mp*.015*dt);if(n===0&&!m.watch){if(m.queued&&m.time>m.queued.until)m.queued=null;if(m.queued){if(arenaAction(m,n,m.queued.index))m.queued=null;}else if(m.autoBasic)arenaAction(m,n,null);continue;}const d=Math.abs(t.x-f.x),dir=Math.sign(t.x-f.x)||1,desired=f.st.range>=5?Math.min(8,f.st.range*.7):1.6;if(d>desired+.4)arenaMove(m,n,dir,dt);else if(d<desired-.4&&f.st.range>=5)arenaMove(m,n,-dir,dt);if(!f.potion&&f.hp<f.st.hp*.3){f.potion=true;f.hp=Math.min(f.st.hp,f.hp+f.st.hp*.15);m.events.push({time:m.time,n,label:'Poção · uso único',damage:0});}
 const kit=KITS[f.classId],support=kit.findIndex((k,i)=>!k.coef&&f.cd[i]<=0&&f.mp>=k.cost&&['crit','haste','amp','horizon','dance','night','barrier','iron'].includes(k.kind));if(support>=0&&arenaAction(m,n,support))continue;const choices=kit.map((k,i)=>({k,i})).filter(({k,i})=>k.coef>0&&f.cd[i]<=0&&d<=k.range&&f.mp>=k.cost&&f.level>=(SKILL_UNLOCK[i]||1));choices.sort((a,b)=>b.k.coef-a.k.coef);if(choices.length&&arenaAction(m,n,choices[0].i))continue;arenaAction(m,n,null);}
 const due=[];for(const h of m.pending){h.wait-=dt;if(h.wait<=0)due.push(h);}m.pending=m.pending.filter(h=>h.wait>0);for(const h of due){const f=m.fighters[h.n],t=m.fighters[1-h.n];if(Math.abs(f.x-t.x)>(h.index===null?f.st.range:KITS[f.classId][h.index].range)+2){m.events.push({time:m.time,n:h.n,label:'Alvo escapou',damage:0});continue;}const st={...f.st,penF:f.st.penF,penM:f.st.penM};const hit=resolveStrike(st,f.classId,t.st,{index:h.index,coefficient:h.coefficient,pvp:true,rng:m.rng,critBonus:f.buffs.crit>0?.12:0,ampBonus:f.buffs.amp>0?.15:0});let dmg=hit.value*(t.buffs.iron>0?.5:1),absorb=Math.min(t.shield,dmg);t.shield-=absorb;dmg-=absorb;f.damage+=Math.min(t.hp,dmg);t.hp=Math.max(0,t.hp-dmg);if(!hit.miss)t.stun=Math.max(t.stun,h.stun*(1-t.st.ten));m.events.push({time:m.time,n:h.n,label:h.index===null?'Ataque básico':KITS[f.classId][h.index].name,damage:Math.round(dmg),critical:hit.critical,miss:hit.miss});}
 m.events=m.events.slice(-25);if(m.fighters.some(f=>f.hp<=0)||m.time>=90){m.done=true;m.winner=m.fighters[0].hp<=0&&m.fighters[1].hp<=0?null:m.fighters[0].hp<=0?1:m.fighters[1].hp<=0?0:null;}}
